<?php
require_once __DIR__.'/../includes/bootstrap.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){flash('warning','Frete não encontrado.');redirect('fretes/index.php');}
$q=db()->prepare("SELECT f.*,t.nome AS transportador,t.documento,t.tipo_documento,t.telefone,ao.cep AS cep_origem,ao.rua AS rua_origem,ao.numero AS numero_origem,ao.bairro AS bairro_origem,ao.cidade AS cidade_origem,ao.estado AS estado_origem,ad.cep AS cep_destino,ad.rua AS rua_destino,ad.numero AS numero_destino,ad.bairro AS bairro_destino,ad.cidade AS cidade_destino,ad.estado AS estado_destino FROM fretes f JOIN transportadores t ON t.id=f.transportador_id JOIN enderecos ao ON ao.id=f.origem_id JOIN enderecos ad ON ad.id=f.destino_id WHERE f.id=?");$q->execute([$id]);$frete=$q->fetch();if(!$frete){flash('warning','Frete não encontrado.');redirect('fretes/index.php');}$q=db()->prepare('SELECT p.codigo,p.nome,p.peso,p.valor,fp.quantidade,(p.valor*fp.quantidade) AS subtotal FROM frete_produtos fp JOIN produtos p ON p.id=fp.produto_id WHERE fp.frete_id=? ORDER BY p.nome');$q->execute([$id]);$items=$q->fetchAll();$pageTitle='Detalhes do frete';$current='fretes';require __DIR__.'/../includes/header.php';?>
<div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3"><div><a href="<?=e(url('fretes/index.php'))?>">← Voltar para fretes</a><h1 class="h3 mt-2 mb-0">Frete <?=e($frete['codigo'])?></h1></div><a class="btn btn-outline-secondary" href="<?=e(url('relatorios/index.php?data='.$frete['data_frete']))?>">Relatório da data</a></div>
<div class="row g-3 mb-3"><div class="col-md-4"><div class="card card-body h-100"><div class="text-secondary small">Data do frete</div><strong><?=e(date_br($frete['data_frete']))?></strong></div></div><div class="col-md-4"><div class="card card-body h-100"><div class="text-secondary small">Transportador</div><strong><?=e($frete['transportador'])?></strong><span class="small text-secondary"><?=e($frete['tipo_documento'].' '.$frete['documento'].' · '.$frete['telefone'])?></span></div></div><div class="col-md-4"><div class="card card-body h-100"><div class="text-secondary small">Total de itens</div><strong><?=count($items)?> produto(s)</strong></div></div></div>
<div class="row g-3 mb-3"><div class="col-md-6"><div class="card card-body h-100"><h2 class="h6">Origem</h2><?=e($frete['rua_origem'].', '.$frete['numero_origem'])?><br><?=e($frete['bairro_origem'])?><br><?=e($frete['cidade_origem'].'/'.$frete['estado_origem'])?><br><span class="small text-secondary">CEP: <?=e($frete['cep_origem'])?></span></div></div><div class="col-md-6"><div class="card card-body h-100"><h2 class="h6">Destino</h2><?=e($frete['rua_destino'].', '.$frete['numero_destino'])?><br><?=e($frete['bairro_destino'])?><br><?=e($frete['cidade_destino'].'/'.$frete['estado_destino'])?><br><span class="small text-secondary">CEP: <?=e($frete['cep_destino'])?></span></div></div></div>
<div class="card shadow-sm"><div class="card-header bg-white"><h2 class="h5 mb-0">Produtos do frete</h2></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Código</th><th>Produto</th><th>Peso (kg)</th><th>Quantidade</th><th>Valor unitário</th><th>Subtotal informativo</th></tr></thead><tbody><?php $total=0;foreach($items as $item):$total+=(float)$item['subtotal'];?><tr><td><?=e($item['codigo'])?></td><td><?=e($item['nome'])?></td><td><?=e($item['peso'])?></td><td><?=(int)$item['quantidade']?></td><td><?=e(money($item['valor']))?></td><td><?=e(money($item['subtotal']))?></td></tr><?php endforeach;?></tbody><tfoot><tr><th colspan="5" class="text-end">Soma informativa dos valores dos produtos</th><th><?=e(money($total))?></th></tr></tfoot></table></div></div>
<?php if($frete['observacoes']):?><div class="card card-body mt-3"><h2 class="h6">Observações</h2><?=nl2br(e($frete['observacoes']))?></div><?php endif;?>
<?php require __DIR__.'/../includes/footer.php';?>
